export const pageQuery = graphql`
  query IndexPageQuery {
    projects: allMdx(
      filter: {
        internal: { contentFilePath: { regex: "//projects//" } }
        frontmatter: { feat: { eq: true } }
      }
      sort: { frontmatter: { date: DESC } }
    ) {
      edges {
        node {
          id
          fields {
            slug
          }
          frontmatter {
            title
            date(formatString: "DD MMMM YYYY")
            logo {
              publicURL
            }
          }
        }
      }
    }
  }
`;
